def SoE(n):
	a = []
	prime = [True for i in range(n + 1)]
	p = 2
	while p * p <= n:
		if prime[p] == True:
			for i in range(p * p, n + 1, p):
				prime[i] = False
		p += 1
	for p in range(2, n + 1):
		if prime[p]:
			a.append(p)
	return (prime, a)

def binary_search(l, r, a, tar):
	if l > r:
		return -1
	m = (l + r) // 2
	if a[m] == tar:
		return m
	elif a[m] < tar:
		return binary_search(m + 1, r, a, tar)
	else:
		return binary_search(l, m - 1, a, tar)
t = int(input())
(a, b) = SoE(100000)
for _ in range(t):
	n = int(input())
	i = n - 1
	while a[i] == False:
		i -= 1
	p = i
	left = n
	curr = binary_search(0, len(b) - 1, b, p)
	value = n * p
	ans = 0
	while left > 0:
		num = value // b[curr]
		if b[curr] == 2:
			pass
		elif num % 2 == 1:
			num = num - 1
		if left - num >= 0:
			left -= num
			ans = num * b[curr]
			curr = curr - 1
		elif b[curr] == 2:
			ans = ans + b[curr] * left
			left = 0
		elif left % 2 == 1:
			ans = ans + b[curr] * (left - 1)
			left = 1
			curr = curr - 1
		else:
			ans = ans + b[curr] * left
			left = 0
			curr = curr - 1
	print(ans // 2)
